#include <iostream>
#include <vector>
#include <cmath>

int main() {
    int n, M;
    std::cin >> n >> M;

    std::vector<long long> dp_list(n + 1, 0);
    std::vector<long long> accu_list(n + 1, 0);

    dp_list[1] = 1;
    if (n >= 2) {
        dp_list[2] = 1;
    }
    accu_list[1] = 1;
    if (n >= 2) {
        accu_list[2] = 2;
    }

    for (int i = 3; i <= n; ++i) {
        dp_list[i] = accu_list[i - 1];
        int max_div = static_cast<int>(std::sqrt(i));
        for (int divisor = 1; divisor <= max_div; ++divisor) {
            if (i % divisor == 0) {
                dp_list[i] += dp_list[divisor];
                dp_list[i] %= M;
                if (divisor > 1 && divisor * divisor < i) {
                    dp_list[i] += dp_list[i / divisor];
                    dp_list[i] %= M;
                }
            }
        }
        accu_list[i] = (accu_list[i - 1] + dp_list[i]) % M;
    }

    std::cout << accu_list[n] << std::endl;
    return 0;
}
